// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.util.Arrays;
import java.util.Locale;

import org.junit.jupiter.api.Test;

class LeoPlusReplayPrototypeTest {

	private static final LogicalLearningKey LOGICAL = LogicalLearningKey.of(
			"join", "replay-expression", "replay-children", "replay-predicates", "v0,v1", "none",
			"bag|duplicate-sensitive|sparql-unbound", "store-defaults");
	private static final LearningApplicability APPLICABILITY = new LearningApplicability(
			0x51L, 0L, "input:unbound|range:unknown|guarantee:measure_unbiased", 7L, 11L, 1L);
	private static final PhysicalResidualKey MATERIALIZED = physical("materialized-hash");
	private static final PhysicalResidualKey STREAMING = physical("streaming-correlated");

	@Test
	void chronologicalReplayMeetsSyntheticSafetyGatesAndRestartsDeterministically() throws Exception {
		FrontierLearningModel model = new FrontierLearningModel();
		StringBuilder replay = new StringBuilder(
				"sequence,phase,predicted,actual,nigPoint,combinedPoint,lower,upper,gate,ood,"
						+ "conventionalQError,nigQError,combinedQError,regret,planSwitch,lifecycle\n");
		long epoch = 1L;
		for (int observation = 0; observation < 32; observation++) {
			double predicted = 96.0d + observation % 9;
			double actual = predicted * 4.0d + observation % 3 - 1.0d;
			appendReplayRow(replay, model, epoch, "training", predicted, actual);
			model.observeLogical(LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS,
					LearningFeatureEnvelope.conventionalRows(predicted), actual, epoch++);
		}

		double[] heldOutPredicted = { 98.0d, 100.0d, 102.0d, 1.0e9d, 2.0e9d };
		double[] heldOutActual = { 392.0d, 401.0d, 408.0d, 1.0e9d, 2.0e9d };
		double[] conventionalQError = new double[heldOutPredicted.length];
		double[] nigQError = new double[heldOutPredicted.length];
		double[] combinedQError = new double[heldOutPredicted.length];
		double[] regret = new double[heldOutPredicted.length];
		int covered = 0;
		for (int index = 0; index < heldOutPredicted.length; index++) {
			double predicted = heldOutPredicted[index];
			double actual = heldOutActual[index];
			FrontierLearningModel.DimensionEstimate nig = rawNigEstimate(model, predicted);
			FrontierLearningModel.DimensionDecision combined = combinedDecision(model, predicted);
			double combinedPoint = combined.estimate() == null ? predicted : combined.estimate().correctedValue();
			double lower = combined.estimate() == null ? predicted : combined.estimate().lowerValue();
			double upper = combined.estimate() == null ? predicted : combined.estimate().upperValue();
			conventionalQError[index] = qError(predicted, actual);
			nigQError[index] = qError(nig.correctedValue(), actual);
			combinedQError[index] = qError(combinedPoint, actual);
			regret[index] = planRegret(combinedPoint, actual);
			covered += actual >= lower && actual <= upper ? 1 : 0;
			appendReplayRow(replay, model, epoch++, "held-out", predicted, actual);
		}

		assertEquals(LearningGateDecision.Outcome.APPLICABLE,
				combinedDecision(model, 100.0d).gate().outcome());
		assertEquals(LearningGateDecision.Outcome.OUT_OF_DISTRIBUTION,
				combinedDecision(model, 1.0e9d).gate().outcome());
		assertTrue(median(combinedQError) <= median(conventionalQError));
		assertTrue(median(combinedQError) <= median(nigQError));
		assertTrue(percentile95(regret) <= 0.10d);
		assertEquals(heldOutPredicted.length, covered,
				"The declared synthetic predictive interval must cover every held-out observation");

		FrontierLearningModel restored = roundTrip(model);
		for (double predicted : heldOutPredicted) {
			FrontierLearningModel.DimensionDecision before = combinedDecision(model, predicted);
			FrontierLearningModel.DimensionDecision after = combinedDecision(restored, predicted);
			assertEquals(before.gate().outcome(), after.gate().outcome());
			if (before.estimate() != null) {
				assertNotNull(after.estimate());
				assertEquals(before.estimate().correctedValue(), after.estimate().correctedValue(), 0.0d);
				assertEquals(before.estimate().lowerValue(), after.estimate().lowerValue(), 0.0d);
				assertEquals(before.estimate().upperValue(), after.estimate().upperValue(), 0.0d);
			}
		}
		assertPeriodTwoContainment();

		System.out.print("LEO_PLUS_REPLAY_BEGIN\n" + replay + "LEO_PLUS_REPLAY_END\n");
	}

	private static void appendReplayRow(StringBuilder replay, FrontierLearningModel model, long sequence,
			String phase, double predicted, double actual) {
		FrontierLearningModel.DimensionEstimate nig = rawNigEstimate(model, predicted);
		FrontierLearningModel.DimensionDecision combined = combinedDecision(model, predicted);
		double nigPoint = nig == null ? predicted : nig.correctedValue();
		double combinedPoint = combined.estimate() == null ? predicted : combined.estimate().correctedValue();
		double lower = combined.estimate() == null ? predicted : combined.estimate().lowerValue();
		double upper = combined.estimate() == null ? predicted : combined.estimate().upperValue();
		double regret = planRegret(combinedPoint, actual);
		boolean selectedAlternative = combinedPoint > 220.0d;
		replay.append(String.format(Locale.ROOT,
				"%d,%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%s,%s,%.6f,%.6f,%.6f,%.6f,%s,MONITORING%n",
				sequence, phase, predicted, actual, nigPoint, combinedPoint, lower, upper,
				combined.gate().outcome(),
				combined.gate().outcome() == LearningGateDecision.Outcome.OUT_OF_DISTRIBUTION,
				qError(predicted, actual), qError(nigPoint, actual), qError(combinedPoint, actual), regret,
				selectedAlternative));
	}

	private static FrontierLearningModel.DimensionDecision combinedDecision(FrontierLearningModel model,
			double predicted) {
		return model.logicalDecision(LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS,
				LearningFeatureEnvelope.conventionalRows(predicted), predicted);
	}

	private static FrontierLearningModel.DimensionEstimate rawNigEstimate(FrontierLearningModel model,
			double predicted) {
		return FrontierLearningModel.estimateLogical(
				model.logicalPosterior(LOGICAL, APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS),
				FrontierCostDimension.OUTPUT_ROWS, predicted);
	}

	private static FrontierLearningModel roundTrip(FrontierLearningModel model) throws Exception {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (DataOutputStream output = new DataOutputStream(bytes)) {
			model.writeTo(output);
		}
		try (DataInputStream input = new DataInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			return FrontierLearningModel.readFrom(input);
		}
	}

	private static void assertPeriodTwoContainment() {
		PlanLifecycleStore lifecycle = new PlanLifecycleStore(16);
		PlanLifecycleStore.ObjectiveEnvelope firstA = envelope(90.0d, 100.0d, 110.0d);
		PlanLifecycleStore.ObjectiveEnvelope firstB = envelope(60.0d, 70.0d, 80.0d);
		PlanLifecycleStore.ObjectiveEnvelope secondA = envelope(25.0d, 30.0d, 35.0d);
		PlanLifecycleStore.ObjectiveEnvelope secondB = envelope(15.0d, 20.0d, 24.0d);
		lifecycle.observe(LOGICAL, MATERIALIZED, APPLICABILITY, firstA, 100.0d, true,
				Double.POSITIVE_INFINITY, 1L);
		lifecycle.decision(LOGICAL, STREAMING, APPLICABILITY, firstB, true);
		lifecycle.observe(LOGICAL, STREAMING, APPLICABILITY, firstB, 70.0d, true, 110.0d, 2L);
		lifecycle.decision(LOGICAL, MATERIALIZED, APPLICABILITY, secondA, true);
		lifecycle.observe(LOGICAL, MATERIALIZED, APPLICABILITY, secondA, 30.0d, true, 80.0d, 3L);
		lifecycle.decision(LOGICAL, STREAMING, APPLICABILITY, secondB, true);
		lifecycle.observe(LOGICAL, STREAMING, APPLICABILITY, secondB, 20.0d, true, 35.0d, 4L);
		assertEquals(PlanLifecycleStore.State.BLOCKED,
				lifecycle.decision(LOGICAL, STREAMING, APPLICABILITY, secondB, true).state());
	}

	private static PlanLifecycleStore.ObjectiveEnvelope envelope(double lower, double point, double upper) {
		return new PlanLifecycleStore.ObjectiveEnvelope(lower, point, upper);
	}

	private static PhysicalResidualKey physical(String algorithm) {
		return PhysicalResidualKey.of(algorithm, "statement-pattern", "spoc", "per-binding", "none", "none",
				"none", "bound");
	}

	private static double qError(double predicted, double actual) {
		double safePredicted = Math.max(1.0d, predicted);
		double safeActual = Math.max(1.0d, actual);
		return Math.max(safePredicted / safeActual, safeActual / safePredicted);
	}

	private static double planRegret(double estimatedFirst, double actualFirst) {
		double alternative = 220.0d;
		double selected = estimatedFirst <= alternative ? actualFirst : alternative;
		return (selected - Math.min(actualFirst, alternative)) / Math.min(actualFirst, alternative);
	}

	private static double median(double[] values) {
		double[] sorted = values.clone();
		Arrays.sort(sorted);
		return sorted[sorted.length / 2];
	}

	private static double percentile95(double[] values) {
		double[] sorted = values.clone();
		Arrays.sort(sorted);
		return sorted[(int) Math.ceil(sorted.length * 0.95d) - 1];
	}
}
